import numpy as np
import vipyr as vp

def helical_valley(x):
    th = np.arctan(x[1] / x[0]) / (2.0 * np.pi)
    if x[0] < 0.0:
        th = th + 0.5
    return np.array([10.0 * (x[2] - 10.0 * th), 10.0 * (np.sqrt(x[0] ** 2 + x[1] ** 2) - 1.0), x[2]])

r = vp.optimize.root(helical_valley, [-1.0, 0.0, 0.0])
print(r.x, r.nfev, r.njev)
assert r.check()

